```json
{
  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) t WHERE service_name='ts-order-other-service' AND span_name='SELECT ts.orders_other' GROUP BY 1,2", "claim": "ts.orders_other SELECT client spans p95 rose from about 0.4 ms to about 416 ms in the incident window."},
        {"kind": "trace", "sql": "SELECT p, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) t WHERE service_name='ts-order-other-service' AND span_name IN ('SELECT other.entity.Order','OrderOtherRepository.findByAccountId') GROUP BY 1,2", "claim": "Inside the service, the entity SELECT and repository spans are slow, while the rest of the service path is near normal."},
        {"kind": "metric", "sql": "SELECT metric, round(avg(CASE WHEN p='norm' THEN value END),3) norm_avg, round(avg(CASE WHEN p='abn' THEN value END),3) abn_avg FROM (SELECT 'abn' p, * FROM abnormal_metrics UNION ALL SELECT 'norm', * FROM normal_metrics) WHERE attr_k8s_deployment_name='ts-order-other-service' AND metric IN ('container.cpu.usage','container.memory.working_set','k8s.container.restarts') GROUP BY 1", "claim": "Order-other pod CPU, memory and restarts stay flat, so the slowdown is not resource saturation."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-other-service",
      "to": "ts-admin-order-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(s.duration,0.95)/1e6,1) callee_srv_p95 FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) s JOIN (SELECT 'abn' p2, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) c ON c.p2=s.p AND c.span_id=s.parent_span_id AND c.trace_id=s.trace_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND s.service_name='ts-order-other-service' AND c.service_name='ts-admin-order-service' GROUP BY 1,2,3", "claim": "ts-admin-order-service client calls to ts-order-other-service rose from about 5 ms to about 1299 ms p95."}
      ]
    },
    {
      "from": "ts-admin-order-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, service_name, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) t WHERE service_name='ts-ui-dashboard' AND span_name='GET /api/v1/adminorderservice/adminorder' GROUP BY 1,2,3", "claim": "The user-facing dashboard GET adminorder endpoint p95 rose from about 17 ms to about 1448 ms."}
      ]
    }
  ]
}
